package sem

import (
	"os"
	"path/filepath"
	"testing"
	"time"
)

func TestZZConfirmLeads(t *testing.T) {
	old := time.Now().Add(-48 * time.Hour)
	t.Run("newer", func(t *testing.T) {
		c := t.TempDir()
		p := cachePruneDir(t, c, "search", "search-snapshot-v9999-9999", old)
		PruneStaleCacheVersions(c)
		if _, err := os.Stat(p); err != nil {
			t.Errorf("newer removed: %v", err)
		}
	})
	t.Run("symlinkFamily", func(t *testing.T) {
		c := t.TempDir()
		outside := t.TempDir()
		p := filepath.Join(outside, "search-snapshot-v1-1")
		os.MkdirAll(p, 0o755)
		os.WriteFile(filepath.Join(p, "data"), []byte("x"), 0o644)
		os.Chtimes(p, old, old)
		if err := os.Symlink(outside, filepath.Join(c, "search")); err != nil {
			t.Skip(err)
		}
		PruneStaleCacheVersions(c)
		if _, err := os.Stat(p); err != nil {
			t.Errorf("outside dir removed through symlinked family: %v", err)
		}
	})
	t.Run("heldLock", func(t *testing.T) {
		c := t.TempDir()
		p := cachePruneDir(t, c, "search", "search-snapshot-v1-1", time.Time{})
		f, err := os.OpenFile(filepath.Join(p, "k.build.lock"), os.O_RDWR|os.O_CREATE, 0o600)
		if err != nil {
			t.Fatal(err)
		}
		defer f.Close()
		if err := tryLockBuildLockFile(f); err != nil {
			t.Fatal(err)
		}
		os.Chtimes(p, old, old)
		PruneStaleCacheVersions(c)
		if _, err := os.Stat(p); err != nil {
			t.Errorf("dir with held lock removed: %v", err)
		}
	})
}
EOF
go test ./internal/sem/ -run 'TestZZConfirmLeads|TestPruneStale' -count=1 2>&1 | tail -20

